1	export type EventCat = 'strike' | 'grapple' | 'state' | 'round' | 'event';
2	
3	export function deriveEventCat(desc: string): EventCat {
4	  if (/\bround\b/i.test(desc)) return 'round';
5	  if (/punch|jab|cross|hook|uppercut|elbow|knee|strike|hit|landed|blocked|kick/i.test(desc)) return 'strike';
6	  if (/takedown|grapple|mount|guard|submission|sprawl/i.test(desc)) return 'grapple';
7	  if (/ground|clinch/i.test(desc)) return 'grapple';
8	  return 'state';
9	}
10	
11	export function eventColor(cat: EventCat, sub?: string): string {
12	  if (cat === 'strike') return sub && /knockdown/i.test(sub) ? 'var(--f-red)' : 'var(--accent)';
13	  if (cat === 'grapple') return 'var(--orange-400)';
14	  if (cat === 'state')   return 'var(--slate-400)';
15	  if (cat === 'round')   return 'var(--green-500)';
16	  if (cat === 'event')   return 'var(--purple-600)';
17	  return 'var(--text-muted)';
