38	  const [deleteError, setDeleteError] = useState<string | null>(null);
39	
40	  const { fights } = useFights();
41	  const selectedFight = fights.find(f => f.id === fightId) ?? null;
42	  const { events, loading: eventsLoading } = useEvents(fightId);
43	  const { frameMap } = useFighterFrames(fightId);
44	  const { rounds } = useRounds(fightId);
45	  const width = useWindowWidth();
46	  const narrow = width < 1100;
47	
48	  const fps = selectedFight?.fps ?? 30;
49	  fpsRef.current = fps;
50	
51	  const isProcessing = selectedFight !== null && !isFightViewable(selectedFight.state);
52	
53	  useEffect(() => {
54	    const video = videoRef.current;
55	    if (!video) return;
56	    if (!isPlaying) {
57	      if (rafRef.current !== null) {
