59	        rafRef.current = null;
60	      }
61	      return;
62	    }
63	    const tick = (_now: DOMHighResTimeStamp, metadata: VideoFrameCallbackMetadata) => {
64	      const frame = Math.floor(metadata.mediaTime * fpsRef.current) + 1;
65	      overlayRef.current?.draw(frame);
66	      if (frame !== lastFrameRef.current) {
67	        lastFrameRef.current = frame;
68	        setCurrentTime(metadata.mediaTime);
69	      }
70	      rafRef.current = video.requestVideoFrameCallback(tick);
71	    };
72	    rafRef.current = video.requestVideoFrameCallback(tick);
73	    return () => {
74	      if (rafRef.current !== null) {
75	        video.cancelVideoFrameCallback(rafRef.current);
76	        rafRef.current = null;
77	      }
78	    };
