import { useRef, useState, useEffect } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { useEvents } from '../hooks/useEvents';
import { useFights } from '../hooks/useFights';
import { useFighterFrames } from '../hooks/useFighterFrames';
import { useRounds } from '../hooks/useRounds';
import { useWindowWidth } from '../hooks/useWindowWidth';
import { isFightViewable } from '../types/Fight';
import { deleteFight } from '../services/api';
import ConfirmDialog from '../components/ConfirmDialog';
import VideoPlayer from '../components/VideoPlayer';
import VideoControls from '../components/VideoControls';
import FrameInfo from '../components/FrameInfo';
import FighterOverlay, { type FighterOverlayHandle } from '../components/FighterOverlay';
import LiveFeed from '../components/player/LiveFeed';
import FightStatistics from '../components/player/FightStatistics';
import Momentum from '../components/player/Momentum';
import MatchupCard from '../components/player/MatchupCard';
import FightPurposeBadge from '../components/FightPurposeBadge';

export default function Player() {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const fightId = id ? Number(id) : null;

  const videoRef = useRef<HTMLVideoElement>(null);
  const overlayRef = useRef<FighterOverlayHandle>(null);
  const rafRef = useRef<number | null>(null);
  const fpsRef = useRef<number>(30);
  const lastFrameRef = useRef<number>(-1);
  const [isPlaying, setIsPlaying] = useState(false);
  const [currentTime, setCurrentTime] = useState(0);
  const [duration, setDuration] = useState(0);
  const [showBoxes, setShowBoxes] = useState(true);
  const [showSkeletons, setShowSkeletons] = useState(false);
  const [confirmDelete, setConfirmDelete] = useState(false);
  const [deleting, setDeleting] = useState(false);
  const [deleteError, setDeleteError] = useState<string | null>(null);

  const { fights } = useFights();
  const selectedFight = fights.find(f => f.id === fightId) ?? null;
  const { events, loading: eventsLoading } = useEvents(fightId);
  const { frameMap } = useFighterFrames(fightId);
  const { rounds } = useRounds(fightId);
  const width = useWindowWidth();
  const narrow = width < 1100;

  const fps = selectedFight?.fps ?? 30;
  fpsRef.current = fps;

  const isProcessing = selectedFight !== null && !isFightViewable(selectedFight.state);

  useEffect(() => {
    const video = videoRef.current;
    if (!video) return;
    if (!isPlaying) {
      if (rafRef.current !== null) {
        video.cancelVideoFrameCallback(rafRef.current);
        rafRef.current = null;
      }
      return;
    }
    const tick = (_now: DOMHighResTimeStamp, metadata: VideoFrameCallbackMetadata) => {
      const frame = Math.floor(metadata.mediaTime * fpsRef.current) + 1;
      overlayRef.current?.draw(frame);
      if (frame !== lastFrameRef.current) {
        lastFrameRef.current = frame;
        setCurrentTime(metadata.mediaTime);
      }
      rafRef.current = video.requestVideoFrameCallback(tick);
    };
    rafRef.current = video.requestVideoFrameCallback(tick);
    return () => {
      if (rafRef.current !== null) {
        video.cancelVideoFrameCallback(rafRef.current);
        rafRef.current = null;
      }
    };
  }, [isPlaying]);

  const currentFrame = Math.floor(currentTime * fps) + 1;
  const currentMs = Math.floor(currentTime * 1000);

  const videoSrc = selectedFight ? `/fights/${selectedFight.id}/video` : undefined;

  const togglePlay = () => {
    const video = videoRef.current;
    if (!video) return;
    isPlaying ? video.pause() : video.play();
    setIsPlaying(!isPlaying);
  };

  const stepFrame = (delta: number) => {
    const video = videoRef.current;
    if (!video) return;
    video.pause();
    setIsPlaying(false);
    const newTime = Math.min(Math.max(video.currentTime + delta / fps, 0), video.duration);
    video.currentTime = newTime;
    setCurrentTime(newTime);
    overlayRef.current?.draw(Math.floor(newTime * fpsRef.current) + 1);
  };

  const handleSeek = (time: number) => {
    const video = videoRef.current;
    if (!video) return;
    video.currentTime = time;
    setCurrentTime(time);
    overlayRef.current?.draw(Math.floor(time * fpsRef.current) + 1);
  };

  const fightName = selectedFight
    ? selectedFight.video_path.split('/').pop()?.replace(/\.[^/.]+$/, '') ?? ''
    : '';

  const handleDelete = async () => {
    if (fightId === null) return;
    setDeleting(true);
    setDeleteError(null);
    try {
      // The DELETE unlinks the file this <video> is streaming — stop playback
      // (and the requestVideoFrameCallback loop) before pulling it out from under us.
      videoRef.current?.pause();
      setIsPlaying(false);
      await deleteFight(fightId);
      // replace: Back must not return to a now-dead /fights/{id}.
      navigate('/', { replace: true });
    } catch (err) {
      setDeleteError(err instanceof Error ? err.message : 'Failed to delete fight');
      setDeleting(false);
    }
  };

  const currentRound =
    rounds.find(r => currentFrame >= r.start_frame && currentFrame <= r.end_frame)
      ?.round_number ?? '-';

  // Round 1 end in seconds for pace chart playhead
  const r1Round = rounds.find(r => r.round_number === 1);
  const r1EndSeconds = r1Round ? r1Round.end_frame / fps : 0;

  if (isProcessing) {
    return (
      <div style={{
        display: 'flex', flex: 1, alignItems: 'center', justifyContent: 'center',
        minHeight: 'calc(100vh - 58px)', padding: 24,
      }}>
        <div style={{
          textAlign: 'center',
          background: 'rgba(255,255,255,0.04)',
          backdropFilter: 'blur(24px) saturate(160%)',
          WebkitBackdropFilter: 'blur(24px) saturate(160%)',
          border: '1px solid rgba(255,255,255,0.07)',
          borderRadius: 20,
          padding: '48px 56px',
          boxShadow: '0 8px 40px rgba(0,0,0,0.35)',
          maxWidth: 420,
        }}>
          <span className="material-symbols-outlined" style={{
            fontSize: 40, color: '#64748b', display: 'block', marginBottom: 16,
            animation: 'spin 1.5s linear infinite',
          }}>progress_activity</span>
          <h2 style={{
            fontSize: 20, fontWeight: 800, margin: '0 0 10px',
            background: 'linear-gradient(90deg, #f1f5f9, rgba(255,255,255,0.5))',
            WebkitBackgroundClip: 'text', WebkitTextFillColor: 'transparent', backgroundClip: 'text',
          }}>
            This fight is still being processed
          </h2>
          <p style={{ fontSize: 14, color: '#475569', margin: '0 0 20px', lineHeight: 1.6 }}>
            The AI pipeline is analyzing the video. This usually takes a few minutes.
          </p>
          <button
            onClick={() => navigate('/')}
            className="btn-glass"
            style={{ display: 'inline-flex', alignItems: 'center', gap: 6, padding: '8px 16px', fontSize: 13, fontWeight: 600, borderRadius: 8 }}
          >
            <span className="material-symbols-outlined" style={{ fontSize: 16 }}>arrow_back</span>
            Back to fights
          </button>
        </div>
      </div>
    );
  }

  return (
    <div style={{
      position: 'relative',
      zIndex: 1,
      maxWidth: 1500,
      margin: '0 auto',
      padding: narrow ? '16px 14px 48px' : '22px 30px 70px',
    }}>
      {/* Back nav */}
      <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 14 }}>
        <button
          onClick={() => navigate('/')}
          className="btn-glass"
          style={{ display: 'flex', alignItems: 'center', gap: 5, padding: '6px 12px', fontSize: 12, fontWeight: 600, borderRadius: 8 }}
        >
          <span className="material-symbols-outlined" style={{ fontSize: 16 }}>arrow_back</span>
          All Fights
        </button>
        {selectedFight && (
          <span style={{ fontSize: 13, fontWeight: 600, color: 'var(--text-muted)', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
            {fightName}
          </span>
        )}
        {selectedFight && <FightPurposeBadge purpose={selectedFight.purpose} />}
        {selectedFight && (
          <button
            onClick={() => { setDeleteError(null); setConfirmDelete(true); }}
            title="Delete this fight"
            style={{
              marginLeft: 'auto', flexShrink: 0, display: 'inline-flex', alignItems: 'center', gap: 5,
              padding: narrow ? '6px 8px' : '6px 12px', borderRadius: 8,
              border: '1px solid rgba(239,68,68,0.25)', background: 'rgba(239,68,68,0.08)',
              color: '#ef4444', fontSize: 12, fontWeight: 700, cursor: 'pointer', fontFamily: 'inherit',
            }}
          >
            <span className="material-symbols-outlined" style={{ fontSize: 16 }}>delete</span>
            {!narrow && 'Delete'}
          </button>
        )}
      </div>

      <ConfirmDialog
        open={confirmDelete}
        title="DELETE FIGHT?"
        message={
          <>
            <strong style={{ color: 'var(--text-primary)' }}>{fightName}</strong> will be permanently
            deleted — the source video file, all pipeline predictions, hand labels, rounds, and
            tracked fighter frames. This cannot be undone.
          </>
        }
        confirmLabel="Delete fight"
        confirmIcon="delete_forever"
        danger
        busy={deleting}
        error={deleteError}
        onCancel={() => setConfirmDelete(false)}
        onConfirm={handleDelete}
      />

      {/* TOP GRID: video | live feed */}
      <div style={{
        display: 'grid',
        gridTemplateColumns: narrow ? '1fr' : '1fr 410px',
        gap: 16,
        alignItems: 'stretch',
      }}>
        {/* Video column */}
        <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
          {/* Video stage */}
          <VideoPlayer
            ref={videoRef}
            src={videoSrc}
            isPlaying={isPlaying}
            onTimeUpdate={() => { const v = videoRef.current; if (v) setCurrentTime(v.currentTime); }}
            onLoadedMetadata={() => { const v = videoRef.current; if (v) setDuration(v.duration); }}
            onPlay={() => setIsPlaying(true)}
            onPause={() => setIsPlaying(false)}
            onTogglePlay={togglePlay}
            onStepForward={() => stepFrame(1)}
            onStepBackward={() => stepFrame(-1)}
          >
            {selectedFight && (
              <FighterOverlay
                ref={overlayRef}
                frameMap={frameMap}
                fightWidth={selectedFight.width}
                fightHeight={selectedFight.height}
                showBoxes={showBoxes}
                showSkeletons={showSkeletons}
              />
            )}
            {/* Round chip */}
            <div style={{ position: 'absolute', top: 14, left: 16, display: 'flex', gap: 8, alignItems: 'center', pointerEvents: 'none' }}>
              <span style={{ background: 'rgba(0,0,0,0.55)', backdropFilter: 'blur(8px)', color: '#fff', fontSize: 11, fontWeight: 700, padding: '4px 10px', borderRadius: 6, letterSpacing: '0.06em' }}>
                {currentRound === '-' ? 'LOADING…' : `ROUND ${currentRound}`}
              </span>
            </div>
          </VideoPlayer>

          <VideoControls
            isPlaying={isPlaying}
            currentTime={currentTime}
            duration={duration}
            onTogglePlay={togglePlay}
            onSeek={handleSeek}
            onStepBackward={() => stepFrame(-1)}
            onStepForward={() => stepFrame(1)}
          />

          <FrameInfo currentFrame={currentFrame} currentMs={currentMs} fps={fps} />

          {/* Overlay controls */}
          <div style={{ display: 'flex', gap: 16, padding: '6px 2px' }}>
            <label style={{ display: 'flex', alignItems: 'center', gap: 6, cursor: 'pointer', fontSize: 12, color: 'var(--text-muted)', fontWeight: 500 }}>
              <input
                type="checkbox"
                checked={showBoxes}
                onChange={e => setShowBoxes(e.target.checked)}
                style={{ accentColor: 'var(--accent)', width: 14, height: 14, cursor: 'pointer' }}
              />
              Fighter Boxes
            </label>
            <label style={{ display: 'flex', alignItems: 'center', gap: 6, cursor: 'pointer', fontSize: 12, color: 'var(--text-muted)', fontWeight: 500 }}>
              <input
                type="checkbox"
                checked={showSkeletons}
                onChange={e => setShowSkeletons(e.target.checked)}
                style={{ accentColor: 'var(--accent)', width: 14, height: 14, cursor: 'pointer' }}
              />
              Skeletons
            </label>
          </div>
        </div>

        {/* Live feed column */}
        {narrow ? (
          <div style={{ height: 420 }}>
            <LiveFeed
              events={events}
              currentFrame={currentFrame}
              fps={fps}
              onSeek={handleSeek}
            />
          </div>
        ) : (
          <div style={{ position: 'relative' }}>
            <div style={{ position: 'absolute', inset: 0 }}>
              <LiveFeed
                events={events}
                currentFrame={currentFrame}
                fps={fps}
                onSeek={handleSeek}
              />
            </div>
          </div>
        )}
      </div>

      {/* FIGHT STATISTICS */}
      {!eventsLoading && (
        <FightStatistics
          currentFrame={currentFrame}
          events={events}
          fps={fps}
          rounds={rounds}
        />
      )}

      {/* MOMENTUM */}
      <Momentum time={currentTime} duration={duration} r1EndSeconds={r1EndSeconds} events={events} fps={fps} />

      {/* MATCHUP */}
      <MatchupCard />
    </div>
  );
}

import AccGauge from './AccGauge';
import MiniStat from './MiniStat';
import SegBar from './SegBar';
import { fighters, ctrlFmt } from '../../mocks/fightMock';
import type { FighterStats } from '../../mocks/fightMock';

interface FighterColumnProps {
  corner: 'red' | 'blue';
  s: FighterStats;
}

export default function FighterColumn({ corner, s }: FighterColumnProps) {
  const f = fighters[corner];
  return (
    <div className="glass" style={{ padding: '22px 24px', borderTop: `2px solid ${f.color}`, boxShadow: `0 -1px 24px -10px ${f.color}` }}>
      <div style={{ display: 'flex', alignItems: 'center', gap: 12, marginBottom: 18 }}>
        <span style={{ width: 14, height: 14, borderRadius: 4, background: f.color, boxShadow: `0 0 14px ${f.color}`, flexShrink: 0 }} />
        <div>
          <div className="font-display" style={{ fontSize: 38, lineHeight: 0.9, color: 'var(--text-primary)' }}>{f.name}</div>
          <div style={{ fontSize: 12, color: 'var(--text-muted)', fontWeight: 600, marginTop: 2 }}>"{f.nick}" · {f.record} · {f.corner}</div>
        </div>
      </div>
      <div style={{ display: 'flex', gap: 24, alignItems: 'flex-end', marginBottom: 18 }}>
        <div>
          <div className="font-display" style={{ fontSize: 56, lineHeight: 0.85, color: f.color, fontVariantNumeric: 'tabular-nums' }}>
            {s.sig[0]}
          </div>
          <div className="label" style={{ marginTop: 4 }}>Sig. strikes · of {s.sig[1]}</div>
        </div>
        <div style={{ marginLeft: 'auto' }}>
          <AccGauge pct={s.acc} color={f.color} label="Accuracy" />
        </div>
      </div>
      <div style={{ display: 'flex', gap: 10, marginBottom: 18 }}>
        <MiniStat value={`${s.td[0]}/${s.td[1]}`} label="Takedowns" />
        <MiniStat value={ctrlFmt(s.ctrl)} label="Control" />
        <MiniStat value={s.kd} label="Knockdowns" />
        <MiniStat value={s.sub} label="Sub Att" />
      </div>
      <div style={{ marginBottom: 16 }}>
        <div className="label" style={{ marginBottom: 9 }}>Strikes by target</div>
        <SegBar parts={[
          { val: s.head,     color: 'var(--accent)',      label: 'Head'     },
          { val: s.body,     color: 'var(--orange-400)',  label: 'Body'     },
          { val: s.leg,      color: 'var(--green-500)',   label: 'Leg'      },
        ]} />
      </div>
      <div>
        <div className="label" style={{ marginBottom: 9 }}>Strikes by position</div>
        <SegBar parts={[
          { val: s.distance, color: 'var(--cyan-400)',    label: 'Distance' },
          { val: s.clinch,   color: 'var(--purple-600)', label: 'Clinch'   },
          { val: s.ground,   color: 'var(--orange-400)', label: 'Ground'   },
        ]} />
      </div>
    </div>
  );
}

